(5581204, 808322, 101492, '<td valign="top">Kudos for going out on a limb, but doesn''t strike me as a portrait</td>', 'Kudos for going out on a limb, but doesn''t strike me as a portrait', '2009-07-21 00:02:41.000000', NULL, 1),
