(5581210, 808056, 101492, '<td valign="top">not really what I would call a portrait, more of a photojournalistic shot</td>', 'not really what I would call a portrait, more of a photojournalistic shot', '2009-07-21 00:04:47.000000', NULL, 1),
(5581212, 808182, 101492, '<td valign="top">this one really tells a story and asks a lot of questions, nice perspective and I love how the light creates a pink glow at her ponytail</td>', 'this one really tells a story and asks a lot of questions, nice perspective and I love how the light creates a pink glow at her ponytail', '2009-07-21 00:05:38.000000', NULL, 1),
