(5581221, 808178, 101492, '<td valign="top">I like the backlighting</td>', 'I like the backlighting', '2009-07-21 00:10:53.000000', NULL, 1),
(5581223, 807643, 101492, '<td valign="top">This is my pick for the blue, love the pose, the lighting, the HAIR, awesome</td>', 'This is my pick for the blue, love the pose, the lighting, the HAIR, awesome', '2009-07-21 00:11:36.000000', NULL, 1),
(5581226, 808176, 101492, '<td valign="top">looks too much like it was taken with a cellphone for posting on a social networking site</td>', 'looks too much like it was taken with a cellphone for posting on a social networking site', '2009-07-21 00:13:20.000000', NULL, 1),
