(5581231, 807697, 101492, '<td valign="top">not a bad shot, but the graphic on his shirt is very distracting, maybe a little tighter crop to hide the tee would help</td>', 'not a bad shot, but the graphic on his shirt is very distracting, maybe a little tighter crop to hide the tee would help', '2009-07-21 00:16:43.000000', NULL, 1),
