(5586458, 808253, 84765, '<td valign="top">Mr. Pink looks powerfull. I would therefore prefer if the picture has been taken from below, so he would look big. 5 from me.</td>', 'Mr. Pink looks powerfull. I would therefore prefer if the picture has been taken from below, so he would look big. 5 from me.', '2009-07-26 01:11:56.000000', NULL, 1),
(5586476, 807875, 31664, '<td valign="top">I love the colors and details in this one.  Good luck</td>', 'I love the colors and details in this one.  Good luck', '2009-07-26 02:01:01.000000', NULL, 1),
(5586478, 808028, 31664, '<td valign="top">A very interesting portrait.  I would have liked to see a little more emphasis on her not the tattoo for a portrait challenge.  But having said that great light and details and this is still my second highest score of the challenge. 9</td>', 'A very interesting portrait.  I would have liked to see a little more emphasis on her not the tattoo for a portrait challenge.  But having said that great light and details and this is still my second highest score of the challenge. 9', '2009-07-26 02:06:39.000000', NULL, 1),
(5586479, 807651, 31664, '<td valign="top">Great use of duo tone here. Love the light and the details.</td>', 'Great use of duo tone here. Love the light and the details.', '2009-07-26 02:08:10.000000', NULL, 1),
(5586480, 807868, 31664, '<td valign="top">I love you composition in this.  nice soft feel to the lighting</td>', 'I love you composition in this.  nice soft feel to the lighting', '2009-07-26 02:09:31.000000', NULL, 1),
(5586481, 808285, 31664, '<td valign="top">You''ve brought out the character in his face wonderfully.</td>', 'You''ve brought out the character in his face wonderfully.', '2009-07-26 02:10:10.000000', NULL, 1),
(5586529, 808294, 30982, '<td valign="top">I really like the set up and the shot.  Would be even better (maybe) with the fans on.<br/> <br/>Or not.  I think I like it better with them off.</td>', 'I really like the set up and the shot.  Would be even better (maybe) with the fans on. Or not.  I think I like it better with them off.', '2009-07-26 07:56:15.000000', NULL, 1),
(5586530, 807992, 30982, '<td valign="top">Is the tattoo real or temporary?  Whichever, it works to add to the "color" of this, though I think she''s beautiful as is without the added color!</td>', 'Is the tattoo real or temporary?  Whichever, it works to add to the "color" of this, though I think she''s beautiful as is without the added color!', '2009-07-26 07:57:59.000000', NULL, 1),
(5586532, 808290, 30982, '<td valign="top">Beautifully lit, beautiful subject, great pose.</td>', 'Beautifully lit, beautiful subject, great pose.', '2009-07-26 07:58:18.000000', NULL, 1),
(5586575, 808282, 14603, '<td valign="top">Really like this..unobtrusive background,compositionally creative and the subdued colour tone gives a sombre feel to the image which compliments the reflective mood of the subject.<br/> <br/>Good luck.</td>', 'Really like this..unobtrusive background,compositionally creative and the subdued colour tone gives a sombre feel to the image which compliments the reflective mood of the subject. Good luck.', '2009-07-26 10:27:48.000000', NULL, 1),
